public function compareRequestCountAndMax(int $playerId): ?array
{
    $count = $this->createQueryBuilder('pr')
        ->select('COUNT(pr.id)')
        ->where('pr.Player = :playerId')
        ->andWhere('pr.deletedAt IS NULL')
        ->setParameter('playerId', $playerId)
        ->getQuery()
        ->getSingleScalarResult();

    $em = $this->getEntityManager();
    $maxValue = $em->getConnection()->fetchOne(
        "SELECT option_value FROM mtb_option WHERE option_key = 'arrival_alert_max'"
    );

    if ($maxValue !== false && (int) $count >= (int) $maxValue) {
        return ['max_value' => $maxValue];
    }

    return null;
}

